Rules.InvariantScript:
With(
    {
        nextEvent: First(
            Sort(
                Filter(
                    colECCSCutoverSchedule,
                    StartDate >= Today()
                ),
                StartDate,
                SortOrder.Ascending
            )
        )
    },
    If(
        IsBlank(nextEvent.StartDate),
        "No milestone scheduled",
        nextEvent.EventName &
        " | " &
        Text(
            nextEvent.StartDate,
            "[$-en-US]mmmm d, yyyy"
        )
    )
)

With(
    {
        nextEvent: First(
            Sort(
                Filter(
                    colECCSCutoverSchedule,
                    StartDate >= Now()
                ),
                StartDate,
                SortOrder.Ascending
            )
        )
    },
    If(
        IsBlank(nextEvent.StartDate),
        "COUNTDOWN NOT CONFIGURED",
        With(
            {
                totalMinutes: DateDiff(
                    Now(),
                    nextEvent.StartDate,
                    TimeUnit.Minutes
                )
            },
            If(
                totalMinutes <= 0,
                "EVENT ACTIVE",
                Int(totalMinutes / 1440) &
                "d " &
                Mod(
                    Int(totalMinutes / 60),
                    24
                ) &
                "h " &
                Mod(
                    totalMinutes,
                    60
                ) &
                "m"
            )
        )
    )
)

With(
    {
        grouped: GroupBy(
            cmpECCSCutoverReadinessDsh.ReadinessSummaries,
            'Worksheet Name',
            StatusRows
        )
    },
    AddColumns(
        grouped As ws,
        MappedCount,
        Sum(
            Filter(
                ws.StatusRows,
                'Readiness Status' = "Mapped"
            ),
            'Record Count'
        ),
        NeedsCount,
        Sum(
            Filter(
                ws.StatusRows,
                'Readiness Status' = "Needs Mapping"
            ),
            'Record Count'
        ),
        IncompleteCount,
        Sum(
            Filter(
                ws.StatusRows,
                'Readiness Status' = "Incomplete"
            ),
            'Record Count'
        )
    )
)

With(
    {
        grouped: GroupBy(
            cmpECCSCutoverReadinessDsh.ReadinessSummaries,
            'Facility Mnemonic',
            StatusRows
        )
    },
    AddColumns(
        grouped As fac,
        MappedCount,
        Coalesce(
            Sum(
                Filter(
                    fac.StatusRows,
                    'Readiness Status' = "Mapped"
                ),
                'Record Count'
            ),
            0
        ),
        NeedsCount,
        Coalesce(
            Sum(
                Filter(
                    fac.StatusRows,
                    'Readiness Status' = "Needs Mapping"
                ),
                'Record Count'
            ),
            0
        ),
        IncompleteCount,
        Coalesce(
            Sum(
                Filter(
                    fac.StatusRows,
                    'Readiness Status' = "Incomplete"
                ),
                'Record Count'
            ),
            0
        )
    )
)

Table(
    {
        EventName: "",
        Phase: "",
        StartDate: Date(2026, 1, 1),
        FinishDate: Date(2026, 1, 1)
    }
)
